import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32 && c != -1)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var value = 0
        while (c > 32 && c != -1) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value * sign
    }
}

fun main() {
    val scanner = FastScanner()
    val v = scanner.nextInt()
    val e = scanner.nextInt()

    if (e == 0) {
        println(0)
        return
    }

    if (v <= 6) {
        println(e)
        return
    }

    val adjacency = Array(v + 1) { mutableListOf<Int>() }

    repeat(e) {
        val a = scanner.nextInt()
        val b = scanner.nextInt()
        adjacency[a].add(b)
        adjacency[b].add(a)
    }

    var foundEmptyIntersection = false
    var minCommonVertices = 20

    outer@ for (j in 1..7) {
        val neighbors = adjacency[j]
        for (i in 1..7) {
            if (i == j) continue

            val otherNeighbors = adjacency[i].toHashSet()
            var commonCount = 0

            for (vertex in neighbors) {
                if (vertex in otherNeighbors) {
                    commonCount++
                }
            }

            if (commonCount == 0) {
                foundEmptyIntersection = true
                break@outer
            } else if (commonCount < minCommonVertices) {
                minCommonVertices = commonCount
            }
        }
    }

    if (foundEmptyIntersection) {
        println(e)
    } else {
        println(e - minCommonVertices)
    }
}

