fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    var tokenizer = StringTokenizer(reader.readLine())
    val v = tokenizer.nextToken().toInt()
    val e = tokenizer.nextToken().toInt()

    if (e == 0) {
        println(0)
        return
    }

    if (v <= 6) {
        println(e)
        return
    }

    val graph = Array(v + 1) { mutableListOf<Int>() }

    repeat(e) {
        tokenizer = StringTokenizer(reader.readLine())
        val a = tokenizer.nextToken().toInt()
        val b = tokenizer.nextToken().toInt()
        graph[a].add(b)
        graph[b].add(a)
    }

    var foundEmpty = false
    var numberOfVertices = 20

    for (j in 1..7) {
        val neighbors = graph[j]
        for (i in 1..7) {
            if (i == j) continue

            val otherNeighbors = graph[i].toHashSet()
            val intersectionSize = neighbors.count { it in otherNeighbors }

            if (intersectionSize == 0) {
                foundEmpty = true
                break
            } else if (intersectionSize < numberOfVertices) {
                numberOfVertices = intersectionSize
            }
        }
    }

    if (foundEmpty) {
        println(e)
    } else {
        println(e - numberOfVertices)
    }
}

